            }
            return FxqClient.parse(line);
        }).rate();
    }

    private String fetch(String pair, LocalDate date) {
        vendorCalls++;
        return client.rate(pair, date);
    }

    private String fetchFrom(String pair, LocalDate date, int source) {
        vendorCalls++;
        return client.rate(pair, date, source);
    }

